/* 名词解释 · 实验心理学 */
window.__MODULES = window.__MODULES || [];
window.__MODULES.push({"module":"term","subject":"实验心理学","icon":"🔬","desc":"郭秀艳《实验心理学》（人民教育出版社 2019）","chapters":[{"name":"第1章 实验心理学概述","items":[{"q":"操作定义","a":"根据测量心理现象的程序来对一个概念下定义，由布里奇曼提出。例如把疲劳定义为从事某种劳动的时间量。操作定义明确了自变量的内涵，同时指出了自变量操纵的方法。"},{"q":"心理学实验","a":"在严格控制的条件下，有组织地逐次变化条件，对伴随的心理现象进行观察、记录和测量，从而确定条件与心理现象的关系。"},{"q":"因素型实验","a":"主要探索所要研究的心理现象产生的条件是什么,与哪些因素有关。"},{"q":"函数型实验","a":"主要研究条件与心理现象的函数关系。因素型实验可以初步探索哪些因素会对结果变量造成影响，从而进行更详细的函数型实验，找到具体的影响效应值。"},{"q":"实验范式","a":"在心理学中，为了验证某种假设以及发现某些有意思的现象，实验者会设计具有验证性目的的实验。有些实验比较经典，被有相同或类似目的的后人多次沿用，就形成了一种实验范式。实验范式就是一种相对固定的实验程序，它包括实验的目的、具体流程、手段以及实验设计等。如启动范式、Stroop 范式、内隐联想范式等。"}]},{"name":"第2章 变量与额外变量","items":[{"q":"变量","a":"（Variable）是指在数量上或质量上可变化，操作和测量的条件、现象或特征。在一个具体的试验中，变量分为自变量、因变量和额外变量。"},{"q":"自变量","a":"即实验者所操纵的、对被试的反应产生影响的变量，也称独立变量或刺激变量"},{"q":"因变量","a":"操纵自变量的变化而引起的被试某种特定反应的变化，也称依从变量或反应变量。"},{"q":"天花板效应","a":"被试的反应超过了所能测量的最大值。天花板效应的出现是由于实验任务过于简单，对于不同水平的自变量，被试都取得了很好的结果。"},{"q":"地板效应","a":"被试反应低于所能测量的最小值。这种效应的出现，必然使实验者的实验不能获得任何有意义的结果。地板效应的出现可能是实验者要求被试完成的任务过于困难，对于各种不同水平的自变量，被试都获得了很差的结果。"},{"q":"额外变量","a":"与实验目的无关但能对被试反应有一定影响的变量，也称控制变量或无关变量。"},{"q":"实验者偏见或实验者效应","a":"由美国著名心理学家罗森塔尔和雅格布森提出，又称皮格马利翁效应、罗森塔尔效应、毕马龙效应、期望效应主试在实验中可能以某种方式（如他的表情、手势、语气等）有意无意地影响被试，使他们的反应符合实验者的期望。常见的实验者效是罗森塔尔效应。"},{"q":"要求特征","a":"被试自发地对实验者的实验目的产生一个假设或猜想，然后再以一种自以为能满足这一假象的实验目的的方式进行反应。"},{"q":"好被试现象","a":"被试在实验过程中根据自己对实验目的的假设而努力使自己的行为符合实验者的要求，成为一个好被试。"},{"q":"霍桑效应","a":"由哈佛大学心理专家乔治·埃尔顿·梅奥教授为首的研究小组提出此概念，是指那些意识到自己正在被别人观察的个人具有改变自己行为的倾向。心理学上的一种要求特征。"},{"q":"安慰剂效应","a":"又称伪药效应、假药效应。病人虽然接受的是无效治疗，但却“相信″ 治疗有效，而让病患症状得到舒缓的现象。被试认为某种无效刺激具有某种功能，从而有意无意中按照这种功能的结果来行动或者是表现出对刺激有效的反应。"}]},{"name":"第3章 实验设计与效度","items":[{"q":"抵消平衡法","a":"采用某些综合平衡的方法，使额外变量的效果互相抵消，达到控制额外变量的目的。常见的抵消平衡法有 ABBA 法和拉丁方设计。"},{"q":"不完全抵消平衡法","a":"一般指拉丁方法。指每个自变量或实验处理都能同等地出现实验顺序的每个位置这样一种设计类型。尽管它不能将所有可能的实验顺序完全平衡，但是它能保证不同的实验处理所受的顺序效应的影响均等。拉丁方法要求自变量与额外变量之间不能存在交互作用，同时要求每个额外变量的水平数必须与自变量的水平数相等。"},{"q":"被试间设计","a":"每个被试只接受一个自变量水平处理的实验设计，又称为组间设计、独立组设计、完全随机设计。"},{"q":"被试内设计","a":"每个被试或被试组接受所有自变量水平处理的实验设计，又称为组内设计、相关组设计、重复测量设计。被试内设计完全不会受到来自被试个体差异的困扰。"},{"q":"混合设计","a":"一个多自变量设计中，有些自变量是被试间变量，有些自变量是被试内变量。"},{"q":"准实验设计","a":"介于真实验设计和非实验设计之间，虽然可以设置控制组，但不能随机选择和分配被试，准实验设计对额外变量的控制比非实验设计严格，但不如真实验设计控制得充分和广泛。"},{"q":"小样本设计","a":"被试内设计的一种变式，实验时向少数几个或单个被试呈现自变量不同水平或处理方式。"},{"q":"相等时间样本设计","a":"使用两个相等的时间样本，在其中的一个时间样本中出现实验处理，另一个时间样本中不出现实验处理。基本模式为：X1 O1 X 0O2 X1 O3 X 0O4。其中，O1、O3表示接受实验处理后的测验结果，O2、O4 表示没有接受实验处理后的测验结果。"},{"q":"交叉滞后组相关设计","a":"要求在时间 1 对两个变量的关系作出测定和相关分析，再在时间 2 作相似测定和分析，求得同步相关系数 rA1B1、rA1B1 和稳定性相关系数 rA1A2、rA1A2。在同步相关稳定的情况下，如果 rA1B2＞rB1A2，可以认为与 B 引起 A 相比较，A 是B 的更强的原因；反之，B 是A 的更强的原因。"},{"q":"完全随机化设计","a":"也称简单随机化设计，是指用随机化方法将被试分为几组，然后依据实验目的对各组被试实施不同的处理。"},{"q":"所罗门四组设计","a":"随机选择被试，并将被试随机分成四组，两组为实验组，两组为控制组，两组有前测，两组无前测，可以分离出前测的反作用效果。"},{"q":"完全随机析因设计","a":"在实验中有两个或两个以上因素（自变量），并且每个因素至少有两个水平，各因素的各个水平互相结合，构成多种组合处理。然后用随机分配的方法将被试分为若干同质组（分组的个数等于实验处理的个数），同时用随机的方法分配每一组被试接受一种实验处理。"},{"q":"交互作用","a":"两个或两个以上的自变量的不同水平之间的相互作用：一个因素的水平在另一个因素的不同水平上变化趋势不一致的现象。"},{"q":"两因素交互作用的含义和检验方法","a":"两因素交互作用，即一个因素的水平在另一个因素的不同水平上变化趋势不一致的现象，即因素和因素的结合，而对因变量产生的影响如果两个因素彼此独立，即不管其中一个因素处于哪种水平，另一个因素的不同水平均值间的差异都保持一致，则不会产生交互作用。产生交互作用时需进行简单效应分析。"},{"q":"主效应","a":"同时考察各自变量对同一因变量的主要影响效应（交互作用不显著时分析) =单独考虑某个因素对因变量产生的影响。"},{"q":"简单效应","a":"考察一个因素的各个水平在另一个因素的某个水平上的效应（交互作用显著时分析)=一个因素的各个水平在另一个因素某水平上的变异。"},{"q":"随机区组设计","a":"先将被试在无关变量上进行匹配，分为若干区组（保证每个区组内部被试尽量同质，区组之间被试尽量异质），然后将每个区组的被试随机分配到自变量的各个水平。"},{"q":"顺序效应","a":"如果被试参加多个实验处理，会产生两种顺序效应。"},{"q":"疲劳效应","a":"疲劳效应是指随着实验的进行，被试因疲劳而导致完成任务的成绩下降。"},{"q":"练习效应","a":"练习效应是指随着实验的进行，被试对完成实验任务的经验越来越多而引起的行为改变。无论是积极的改变，还是消极的改变，实验者将这种随练习而伴随逐渐改变的现象，称为累计误差。"},{"q":"实验效度","a":"实验方法能达到实验目的的程度，也就是实验结果的准确性和有效性程度，可分为内部效度、外部效度、构想效度和统计结论效度。"},{"q":"内部效度","a":"实验中的自变量与因变量之间因果关系的明确程度，内部效度与无关变量的控制有关。"},{"q":"统计回归效应","a":"在实验处理前选择了在某一特征方面具有极端分数（高分或低分）的被试，实验处理后的测验分数有回归到平均数的趋向（变得不优也不差）。"},{"q":"双盲实验","a":"通过在实验过程中让主试和被试都不知晓实验真实意图，从而排除实验者效应和要求特征效应对实验结果污染的方法。"},{"q":"真实验设计","a":"在随机化原则上选择和分配被试，可有效控制额外变量的影响。可分为完全随机化设计和随机区组化设计。"},{"q":"实验设计","a":"实验设计是实验心理学中最基本的问题，它一般包括考察行为的内容、定义总体和样本、变量的选择、建立操作定义、预期变量的关系等步骤。"}]},{"name":"第4章 实验效度","items":[{"q":"外部效度","a":"实验结果能够普遍推论到样本所在的总体和其他同类现象中去的程度，即实验结果的普遍代表性和适用性，又称生态效度。"},{"q":"现场实验","a":"提高实验结果外部效度最好的方法就是在实验室外进行研究。现场实验是指真实生活情景中进行的有控制的实验，所以又称自然实验。克服了实验室实验的缺点虽然也对实验条件进行适当的控制，但往往是在真实生活情境中进行的，被试不知道自己在被研究，因而实验结果真实性高，其局限为对现实情境的控制有限，因而很难得到精密的实验结果。研究可能受到干扰，现场实验中自变量的操作也比较困难。"},{"q":"构想效度","a":"指变量及变量之间关系构想的准确性，以及实验变量在实验时的操作定义与推论时的定义一致性程度，即对所研究的特质在理论上构想的全面性。理论上构想的代表性不足或过于宽泛都会威胁构想效度，如仅将智力定义为数理逻辑能力，或将平时课堂表现纳入期末成绩考核。"},{"q":"统计结论效度","a":"由于统计方法引起的统计结论有效性的程度，它主要反映统计量与总体参数之间的关系。如一个按几何级数变化的数据，若用几何平均数计算统计量，就可能较好地反映总体参数的情况，若选算术平均数作为代表值，就不能很好地代表总体参数，据此得出的统计结论，其效度当然就存在问题。"}]},{"name":"第5章 反应时法","items":[{"q":"反应时","a":"刺激呈现与反应开始之间的时间间隔，也称“反应的潜伏期”。在反应的潜伏期中包含着感觉器官、大脑加工、神经传入传出所需的时间以及肌肉效应器反应所需的时间，其中大脑加工所耗费的时间最多。"},{"q":"生物墙","a":"即刺激强度较弱时，反应时间较长，且随强度增加，反应时会缩短，到一定程度时，反应时会停留在某一水平。"},{"q":"速度—准确率权衡","a":"实验中被试能根据不同的实验要求或在不同的实验条件下，建立一个权衡反应速度与反应准确率的标准来指导他的反应，如有时会以牺牲准确率为代价去换取反应速度，有时则会以牺牲反应速度为代价去换取反应准确率，这就是速度与准确率权衡现象。单一考虑速度或准确率都会损害实验信度，在进行反应时实验时必须同时考虑两个因变量。"},{"q":"减法反应时","a":"一种用相减的方法将反应时分解成各个成分，然后用来分析信息加工过程的方法，又称唐德斯反应时、ABC 反应时。"},{"q":"C反应","a":"C反应，也称辨别反应，指给被试呈现两个或以上的刺激，要求被试对其中特定的刺激作出反应，对其他刺激不作反应，即只作一个反应，对应于多个刺激中的事先规定好的刺激。"}]},{"name":"第6章 心理物理学方法","items":[{"q":"最小变化法","a":"又称极限法、序列探索法、最小可觉差法，是测量阈限的直接方法。其特点是：将刺激按递增或递减系列的方式，以间隔相等的小步变化，寻求从一种反应到另一种反应的瞬时转换点或阈限的位置。"},{"q":"平均差误法","a":"又称调整法、再造法、均等法，其基本程序是主是呈现一个标准刺激，被时再造、复制或调节一个比较刺激，使它与标准刺激相等，是最古老且基本的心理物理学方法之一。"},{"q":"恒定刺激法","a":"恒定刺激法又叫正误法、次数法，是心理物理学中最准确、应用最广的方法，不仅可用于测定阈限，还可以用于测定等值和多种心理值。恒定刺激法中刺激通常由5~7个组成，在实验过程中恒定不变。"},{"q":"信号检测论","a":"信号检测论可以借助两种独立指标分别表示被试的辨别力和反应偏向，从而将阈限测量中的客观感受性和反应偏向、主观动机等区分开来，从而解决了传统心理物理学所无法解决的问题。"},{"q":"辨别力指数","a":"敏感性可以表现为噪音分布与信号加噪音分布之间的分离程度。两者的分离程度越大，敏感性越高；分离程度越小，敏感性越低。噪音分布与信号加噪音分布的分离程度既受信号的物理性质影响，也受被试特性的影响。因此，噪音分布与信号加噪音分布之间的距离就可作为敏感性的指标，称为辨别力d'。"},{"q":"似然比 β","a":"数学定义为：区分信号与噪音反应的心理感受水平所对应的信号分布纵轴与噪音分布纵轴之比。（写出计算公式）"},{"q":"报告标准C","a":"第二个表示反应偏向的指标。报告标准C是表示反应偏向的较为直接的方法,C是横轴上的判定标准位置,即某一感受经验强度。"},{"q":"接受者操作特性曲线","a":"（ROC 曲线）是以虚惊概率为横轴、击中概率为纵轴所组成的坐标图，以被试在特定刺激条件下由于采用不同的判断标准得出的不同结果画出的曲线。"},{"q":"比例量表","a":"比例量表又称等比量表、比率量表，是最高水平的心理物理量表。它既有相等单位，又有绝对零点，可以运用算术的基本运算方法计算。制定比例量表的主要方法有分段法和数量估计法。"},{"q":"心理物理法","a":"心理物理法是实验心理学中的一种重要方法，它主要研究心理量与物理量之间的关系，从而推断出心理活动的规律和特点。"},{"q":"极限法","a":"将刺激按递增或递减系列的方式，以间隔相等的小步变化，寻求一种反应到另一种反应的转折点，即阈限的位置。又叫最小变化法、序列探索法、最小可觉差法。"}]},{"name":"第7章 典型实验与效应","items":[{"q":"麦考乐效应","a":"麦考乐最初的实验分两个阶段。第一阶段，让被试注视红色背景下的纵方向黑白相间的条纹，然后再注视绿色背景下的横方向黑白条纹，并进行轮换。第二阶段，几分钟后，再呈现一个复合刺激（一半横向、一半纵向的黑白相间条纹，不存在彩色背景）。这时，被试会报告说图片上所有白色竖条被看成是绿色，而白色横条被看成紫红色。这是一种颜色适应现象，其后像是适应色的补色。这种颜色互补效应还受测验图形的条纹方向的影响，因此说这是一种随方向而变化的颜色后效。"},{"q":"启动效应","a":"启动效应是指先前的加工活动对随后的加工活动的影响，包括正启动效应和负启动效应。正启动效应也称促进性启动效应，指起促进作用的启动效应。负启动效应也称抑制性启动效应，指起抑制作用的启动效应。"}]},{"name":"第8章 变量控制与统计方法","items":[{"q":"机体变量","a":"机体变量是指可能对被试的心理或行为产生影响的被试自身的特征或身心状态，可分为准自变量和额外变量。"},{"q":"统计控制法","a":"统计控制法是一种实验后控制，指在实验完成后通过一定的统计技术来事后避免实验中额外变量的干扰。"}]}]});
